<?php
namespace App\Modules\Orders\Presentation\Http\Controllers;
use App\Http\Controllers\Controller;use App\Modules\Finance\Domain\Models\FinancialAccount;use App\Modules\Finance\Domain\Models\PaymentAllocation;use App\Modules\Identity\Domain\Models\AuthorizationRequest;use App\Modules\Orders\Domain\Models\SalesOrder;use Illuminate\Http\Request;use Inertia\Inertia;use Inertia\Response;
class ShowSalesOrderController extends Controller {public function __invoke(Request $request,SalesOrder $order):Response{abort_unless($request->user()->hasPermission('orders.view'),403);$order->load(['customer:id,name,phone,email','priceList:id,name','lines.presentation.item:id,name','histories.changer:id,name']);$advances=PaymentAllocation::query()->with('payment')->where('allocatable_type',$order->getMorphClass())->where('allocatable_id',$order->id)->get();$authorizations=AuthorizationRequest::query()->where('resource_type',$order->getMorphClass())->where('resource_id',$order->id)->latest()->get();return Inertia::render('orders/Show',['order'=>[...$order->only(['id','document_number','subtotal','discount','total','advance_amount','balance_amount','notes']),'customer'=>$order->customer->name,'contact'=>$order->customer->phone??$order->customer->email,'price_list'=>$order->priceList->name,'ordered_at'=>$order->ordered_at->format('Y-m-d H:i'),'due_at'=>$order->due_at->format('Y-m-d H:i'),'priority'=>$order->priority->label(),'status'=>$order->status->value,'status_label'=>$order->status->label(),'lines'=>$order->lines->map(fn($l)=>[...$l->only(['id','ordered_quantity','reserved_quantity','produced_quantity','delivered_quantity','list_unit_price','unit_price','discount','line_total','price_reason']),'product'=>"{$l->presentation->item->name} — {$l->presentation->name}"]),'histories'=>$order->histories->sortByDesc('changed_at')->map(fn($h)=>['id'=>$h->id,'from'=>$h->from_status,'to'=>$h->to_status,'at'=>$h->changed_at->format('Y-m-d H:i'),'by'=>$h->changer->name,'notes'=>$h->notes]),'advances'=>$advances->map(fn($a)=>['id'=>$a->id,'amount'=>$a->amount,'paid_at'=>$a->payment->paid_at->format('Y-m-d H:i'),'reference'=>$a->payment->reference])],'accounts'=>FinancialAccount::query()->where('accepts_payments',true)->where('is_active',true)->get(['id','name']),'authorizations'=>$authorizations->map(fn($a)=>['id'=>$a->id,'permission'=>$a->approval_permission,'status'=>$a->status->value,'reason'=>$a->reason,'usable'=>$a->isUsable()]),'canManage'=>$request->user()->hasPermission('orders.manage'),'canRequestAuthorization'=>$request->user()->hasPermission('authorizations.request'),'now'=>now()->format('Y-m-d\TH:i')]);}}
